
import * as THREE from 'three';

// ---------- 渲染 ----------
// 画质档：触屏设备默认「省电」档 —— 关阴影、降分辩率、限 60fps、特效减半
const IS_MOBILE = matchMedia('(pointer:coarse)').matches || /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
const Q = IS_MOBILE
  ? { shadow:false, pixelRatio:0.6, fx:0.18, maxEnemies:80, cullR:18, fps:60, partMax:60, gibMax:40, sparkMax:6, textMax:10, trail:false, fog:false }
  : { shadow:true,  pixelRatio:Math.min(devicePixelRatio, 1.25), fx:1, maxEnemies:150, cullR:32, fps:0, partMax:400, gibMax:220, sparkMax:50, textMax:70, trail:true, fog:true };
const renderer = new THREE.WebGLRenderer({ antialias:false, powerPreference:'high-performance', stencil:false, depth:true });
renderer.setPixelRatio(Q.pixelRatio);
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = Q.shadow;
renderer.shadowMap.autoUpdate = Q.shadow;
renderer.toneMapping = Q.shadow ? THREE.ACESFilmicToneMapping : THREE.NoToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0e1a22);
scene.fog = Q.fog ? new THREE.Fog(0x0e1a22, 38, 75) : null;
const camera = new THREE.PerspectiveCamera(IS_MOBILE ? 70 : 50, innerWidth/innerHeight, 0.1, 200);
const CAM_OFF = IS_MOBILE ? new THREE.Vector3(0, 30, 21) : new THREE.Vector3(0, 20, 14);
let shake = 0, camKick = 0;

scene.add(new THREE.HemisphereLight(0x8fb7d4, 0x1b2a30, 0.9));
const sun = new THREE.DirectionalLight(0xfff1d6, 1.6);
sun.position.set(12, 30, 10); sun.castShadow = Q.shadow;
sun.shadow.mapSize.set(1024, 1024);
Object.assign(sun.shadow.camera, { left:-30, right:30, top:30, bottom:-30, near:1, far:80 });
sun.shadow.bias = -0.0015;
scene.add(sun); scene.add(sun.target);

// ---------- 音效 ----------
let AC = null, NB = null;
function audio(){ if(!AC){ AC = new (window.AudioContext||window.webkitAudioContext)(); } if(AC.state==='suspended') AC.resume(); return AC; }
function noiseBuf(ac, len){ const b = ac.createBuffer(1, ac.sampleRate*len, ac.sampleRate); const d = b.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1; return b; }
function sfxSlash(pitch=1){ try{ const ac = audio(); NB = NB||noiseBuf(ac,0.5); const s = ac.createBufferSource(); s.buffer=NB; const f = ac.createBiquadFilter(); f.type='bandpass'; f.Q.value=1.2; f.frequency.setValueAtTime(600*pitch, ac.currentTime); f.frequency.exponentialRampToValueAtTime(3500*pitch, ac.currentTime+0.12); const g = ac.createGain(); g.gain.setValueAtTime(0.0001, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.5, ac.currentTime+0.03); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.2); s.connect(f).connect(g).connect(ac.destination); s.start(); s.stop(ac.currentTime+0.25);}catch(e){} }
function sfxHit(heavy=false){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='square'; o.frequency.setValueAtTime(heavy?150:240, ac.currentTime); o.frequency.exponentialRampToValueAtTime(40, ac.currentTime+0.13); const g = ac.createGain(); g.gain.setValueAtTime(heavy?0.4:0.25, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.15); o.connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.16); NB = NB||noiseBuf(ac,0.5); const s = ac.createBufferSource(); s.buffer=NB; const f = ac.createBiquadFilter(); f.type='lowpass'; f.frequency.value=heavy?500:1200; const g2 = ac.createGain(); g2.gain.setValueAtTime(0.3, ac.currentTime); g2.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.08); s.connect(f).connect(g2).connect(ac.destination); s.start(); s.stop(ac.currentTime+0.1);}catch(e){} }
function sfxPop(){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='sine'; o.frequency.setValueAtTime(700+Math.random()*300, ac.currentTime); o.frequency.exponentialRampToValueAtTime(120, ac.currentTime+0.1); const g = ac.createGain(); g.gain.setValueAtTime(0.25, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.12); o.connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.13);}catch(e){} }
function sfxHurt(){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='sawtooth'; o.frequency.setValueAtTime(220, ac.currentTime); o.frequency.exponentialRampToValueAtTime(90, ac.currentTime+0.2); const g = ac.createGain(); g.gain.setValueAtTime(0.25, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.22); o.connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.25);}catch(e){} }
function sfxGem(){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='triangle'; o.frequency.setValueAtTime(900, ac.currentTime); o.frequency.exponentialRampToValueAtTime(1600, ac.currentTime+0.06); const g = ac.createGain(); g.gain.setValueAtTime(0.06, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.1); o.connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.1);}catch(e){} }
let gunSfxT = 0;
function sfxGun(){ try{ const ac = audio(); if(ac.currentTime - gunSfxT < 0.04) return; gunSfxT = ac.currentTime; NB = NB||noiseBuf(ac,0.5); const s = ac.createBufferSource(); s.buffer=NB; s.playbackRate.value = 0.7+Math.random()*0.4; const f = ac.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(2500, ac.currentTime); f.frequency.exponentialRampToValueAtTime(300, ac.currentTime+0.07); const g = ac.createGain(); g.gain.setValueAtTime(0.28, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.08); s.connect(f).connect(g).connect(ac.destination); s.start(); s.stop(ac.currentTime+0.09); const o = ac.createOscillator(); o.type='square'; o.frequency.setValueAtTime(120, ac.currentTime); o.frequency.exponentialRampToValueAtTime(50, ac.currentTime+0.05); const g2 = ac.createGain(); g2.gain.setValueAtTime(0.12, ac.currentTime); g2.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.06); o.connect(g2).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.07);}catch(e){} }
// 背景音乐（用户提供，循环播放）
const BGM_B64 = 'data:audio/mpeg;base64,';
const BGM_VOL = 0.35;
let bgmBuf = null, bgmNode = null, bgmGain = null, bgmLoading = false;
function loadBgm(){ if(bgmBuf||bgmLoading) return; bgmLoading = true; try{ const ac = audio(); fetch(BGM_B64).then(r=>r.arrayBuffer()).then(ab=>ac.decodeAudioData(ab)).then(b=>{ bgmBuf=b; if(S.running) startBgm(); }).catch(()=>{}); }catch(e){} }
function startBgm(){ try{ if(!bgmBuf){ loadBgm(); return; } if(bgmNode) return; const ac = audio(); bgmNode = ac.createBufferSource(); bgmNode.buffer = bgmBuf; bgmNode.loop = true; bgmGain = ac.createGain(); bgmGain.gain.setValueAtTime(0.0001, ac.currentTime); bgmGain.gain.exponentialRampToValueAtTime(BGM_VOL, ac.currentTime+1.2); bgmNode.connect(bgmGain).connect(ac.destination); bgmNode.start(); }catch(e){} }
function stopBgm(){ try{ if(bgmNode){ const ac = audio(); bgmGain.gain.setValueAtTime(bgmGain.gain.value, ac.currentTime); bgmGain.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.8); const n = bgmNode; setTimeout(()=>{ try{ n.stop(); }catch(e){} }, 900); bgmNode = null; } }catch(e){} }
let bgmMuted = false;
function toggleBGM(){ bgmMuted = !bgmMuted; const label = document.getElementById('bgmLabel'); if(label){ label.textContent = bgmMuted ? '音乐关' : '音乐开'; } const btn = document.getElementById('bgmBtn'); if(btn){ btn.style.borderColor = bgmMuted ? 'rgba(120,120,120,.5)' : '#3fa9ff88'; btn.style.color = bgmMuted ? '#90a4ae' : '#9fe0ff'; } try{ if(bgmGain && bgmNode){ bgmGain.gain.value = (bgmMuted || S.paused) ? 0 : BGM_VOL; } }catch(e){} }
// 奶龙大笑（Boss 出场用，用户提供的音频）
const LAUGH_B64 = 'data:audio/mpeg;base64,';
let laughBuf = null, laughLoading = false;
function loadLaugh(){ if(laughBuf||laughLoading) return; laughLoading = true; try{ const ac = audio(); fetch(LAUGH_B64).then(r=>r.arrayBuffer()).then(ab=>ac.decodeAudioData(ab)).then(b=>{ laughBuf=b; }).catch(()=>{}); }catch(e){} }
function sfxLaugh(){ try{ const ac = audio(); if(!laughBuf){ loadLaugh(); sfxRoar(); return; } const s = ac.createBufferSource(); s.buffer = laughBuf; const g = ac.createGain(); g.gain.value = 0.9; s.connect(g).connect(ac.destination); s.start(); }catch(e){} }
function sfxRoar(){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='sawtooth'; o.frequency.setValueAtTime(70, ac.currentTime); o.frequency.linearRampToValueAtTime(140, ac.currentTime+0.25); o.frequency.exponentialRampToValueAtTime(45, ac.currentTime+0.9); const f = ac.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(600, ac.currentTime); f.frequency.exponentialRampToValueAtTime(200, ac.currentTime+0.9); const g = ac.createGain(); g.gain.setValueAtTime(0.0001, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.5, ac.currentTime+0.08); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+1.0); o.connect(f).connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+1.05);}catch(e){} }
function sfxSlam(){ try{ const ac = audio(); const o = ac.createOscillator(); o.type='sine'; o.frequency.setValueAtTime(90, ac.currentTime); o.frequency.exponentialRampToValueAtTime(25, ac.currentTime+0.4); const g = ac.createGain(); g.gain.setValueAtTime(0.6, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.45); o.connect(g).connect(ac.destination); o.start(); o.stop(ac.currentTime+0.5); NB = NB||noiseBuf(ac,0.5); const s = ac.createBufferSource(); s.buffer=NB; const f = ac.createBiquadFilter(); f.type='lowpass'; f.frequency.value=400; const g2 = ac.createGain(); g2.gain.setValueAtTime(0.4, ac.currentTime); g2.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime+0.3); s.connect(f).connect(g2).connect(ac.destination); s.start(); s.stop(ac.currentTime+0.3);}catch(e){} }

// ---------- 地面 ----------
const WORLD = 400;
{
  const g = new THREE.PlaneGeometry(WORLD, WORLD, 80, 80); g.rotateX(-Math.PI/2);
  const pos = g.attributes.position, col = [];
  const c1 = new THREE.Color(0x2c5f5a), c2 = new THREE.Color(0x244a4e), c3 = new THREE.Color(0x3a6b5f);
  for (let i=0;i<pos.count;i++){ const x=pos.getX(i), z=pos.getZ(i); pos.setY(i, Math.sin(x*0.15)*Math.cos(z*0.12)*0.25 + (Math.random()-0.5)*0.15); const t=Math.random(); const c = t<0.4?c1:t<0.75?c2:c3; col.push(c.r,c.g,c.b); }
  g.setAttribute('color', new THREE.Float32BufferAttribute(col,3)); g.computeVertexNormals();
  const ground = new THREE.Mesh(g, new THREE.MeshLambertMaterial({ vertexColors:true, flatShading:true })); ground.receiveShadow = true; scene.add(ground);
  const mk = (geo, color, n, sc, yOff, tilt) => {
    const im = new THREE.InstancedMesh(geo, new THREE.MeshLambertMaterial({ color, flatShading:true }), n);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3(), e = new THREE.Euler();
    for (let i=0;i<n;i++){ const r = 8+Math.random()*(WORLD/2-10), a = Math.random()*Math.PI*2; p.set(Math.cos(a)*r, yOff, Math.sin(a)*r); e.set(tilt?(Math.random()-0.5)*0.3:0, Math.random()*Math.PI*2, tilt?(Math.random()-0.5)*0.3:0); q.setFromEuler(e); const k = sc*(0.6+Math.random()*0.8); s.set(k,k*(0.7+Math.random()*0.6),k); m.compose(p,q,s); im.setMatrixAt(i,m); }
    im.castShadow = im.receiveShadow = true; scene.add(im);
  };
  mk(new THREE.DodecahedronGeometry(1,0), 0x55676e, 180, 0.9, 0.2, true);
  mk(new THREE.ConeGeometry(0.5,1.2,4), 0x4c8a5f, 500, 1, 0.5, false);
  mk(new THREE.CylinderGeometry(0.7,0.9,3,6), 0x7a8790, 40, 1, 1.2, true);
}

// ---------- 角色 ----------
const M = (c, extra={}) => new THREE.MeshStandardMaterial({ color:c, flatShading:true, roughness:.85, ...extra });
const player = new THREE.Group(); scene.add(player);
const bodyGroup = new THREE.Group(); player.add(bodyGroup);
const light = new THREE.PointLight(0xa8d8ff, 8, 10); light.position.set(0,2.5,0); player.add(light);
const CH = { sword:null, gun:null };   // 两个角色模型
let cur = null;                         // 当前角色引用 {root, legL, legR, swordPivot?, gunPivot?, barrels?, muzzle?}

function buildSwordsman(){
  const root = new THREE.Group();
  const hakama = M(0x1e2a4a), gi = M(0xe8e4d8), skin = M(0xf0c9a0), hair = M(0x1a1a22), obi = M(0x8e2e2e), sandal = M(0x4a3a2a);
  const legL = new THREE.Group(), legR = new THREE.Group();
  const lgL = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.42, 1.1, 6), hakama); lgL.position.y = -0.55; legL.add(lgL); legL.position.set(-0.3, 1.15, 0);
  const lgR = lgL.clone(); legR.add(lgR); legR.position.set(0.3, 1.15, 0);
  const fL = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.12, 0.5), sandal); fL.position.set(0, -1.1, 0.05); legL.add(fL); legR.add(fL.clone());
  const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.5, 0.85, 7), gi); torso.position.y = 1.55;
  const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.52, 0.52, 0.16, 7), obi); belt.position.y = 1.12;
  const shoulderL = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 5), gi); shoulderL.position.set(-0.5, 1.85, 0); const shoulderR = shoulderL.clone(); shoulderR.position.x = 0.5;
  const armL = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.5, 3, 5), skin); armL.position.set(-0.55, 1.45, 0.15); armL.rotation.x = -0.5;
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.36, 7, 6), skin); head.position.y = 2.32;
  const hairM = new THREE.Mesh(new THREE.SphereGeometry(0.4, 7, 6, 0, Math.PI*2, 0, Math.PI*0.55), hair); hairM.position.y = 2.36;
  const ponytail = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.9, 5), hair); ponytail.position.set(0, 2.35, -0.45); ponytail.rotation.x = 2.5;
  const band = new THREE.Mesh(new THREE.TorusGeometry(0.37, 0.05, 5, 10), obi); band.position.y = 2.42; band.rotation.x = Math.PI/2;
  const bandTail = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.6, 0.03), obi); bandTail.position.set(0.1, 2.15, -0.42); bandTail.rotation.z = 0.3;
  const sheath = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.12, 2.2), M(0x22222a)); sheath.position.set(-0.35, 1.1, -0.6); sheath.rotation.set(0.35, 0.4, 0);
  const swordPivot = new THREE.Group();
  const bladeMat = new THREE.MeshStandardMaterial({ color:0xe6eef5, emissive:0x8ab8ff, emissiveIntensity:0.35, flatShading:true, metalness:0.7, roughness:0.25 });
  const blade = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.02, 2.5), bladeMat); blade.position.z = 1.5;
  const edge = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.03, 2.5), new THREE.MeshBasicMaterial({ color:0xffffff })); edge.position.set(0.05, 0, 1.5);
  const guard = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 0.05, 8), M(0xd4af37, {metalness:.6})); guard.rotation.x = Math.PI/2; guard.position.z = 0.2;
  const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.6, 6), M(0x2a1a3a)); handle.rotation.x = Math.PI/2; handle.position.z = -0.12;
  const armR = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.5, 3, 5), skin); armR.position.set(0, -0.1, -0.15); armR.rotation.x = Math.PI/2 - 0.3;
  const sword = new THREE.Group(); sword.add(blade, edge, guard, handle); sword.position.set(0, -0.55, 0.1);
  const bladeTip = new THREE.Object3D(); bladeTip.position.z = 2.8; const bladeBase = new THREE.Object3D(); bladeBase.position.z = 0.5; sword.add(bladeTip, bladeBase);
  swordPivot.add(armR, sword); swordPivot.position.set(0.55, 1.85, 0); swordPivot.rotation.set(0.3, 0, -0.4);
  root.add(legL, legR, torso, belt, shoulderL, shoulderR, armL, head, hairM, ponytail, band, bandTail, sheath, swordPivot);
  root.traverse(o=>{ if(o.isMesh) o.castShadow = true; });
  return { root, legL, legR, swordPivot, bladeTip, bladeBase, bladeMat };
}
function buildGunner(){
  const root = new THREE.Group();
  const armor = M(0x3b4a3a), dark = M(0x22262a), metal = M(0x8a9199, {metalness:.6, roughness:.4}), orange = M(0xff8a30), skin = M(0xd9b08c);
  const legL = new THREE.Group(), legR = new THREE.Group();
  const lgL = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.3, 1.0, 6), dark); lgL.position.y = -0.5; legL.add(lgL); legL.position.set(-0.32, 1.05, 0);
  const lgR = lgL.clone(); legR.add(lgR); legR.position.set(0.32, 1.05, 0);
  const bL = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.2, 0.6), armor); bL.position.set(0, -1.0, 0.05); legL.add(bL); legR.add(bL.clone());
  const torso = new THREE.Mesh(new THREE.BoxGeometry(1.15, 1.05, 0.75), armor); torso.position.y = 1.65;
  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.65, 0.2), metal); chest.position.set(0, 1.7, 0.42);
  const belt = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.18, 0.8), dark); belt.position.y = 1.1;
  const pack = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.85, 0.45), dark); pack.position.set(0, 1.65, -0.55);
  const packStripe = new THREE.Mesh(new THREE.BoxGeometry(0.92, 0.12, 0.47), orange); packStripe.position.set(0, 1.85, -0.55);
  const shL = new THREE.Mesh(new THREE.SphereGeometry(0.32, 6, 5), armor); shL.position.set(-0.7, 2.05, 0); const shR = shL.clone(); shR.position.x = 0.7;
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.32, 7, 6), skin); head.position.y = 2.5;
  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.4, 7, 6, 0, Math.PI*2, 0, Math.PI*0.6), armor); helmet.position.y = 2.55;
  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.12, 0.12), new THREE.MeshStandardMaterial({ color:0xff8a30, emissive:0xff6a10, emissiveIntensity:1.5 })); visor.position.set(0, 2.5, 0.3);
  const armL = new THREE.Mesh(new THREE.CapsuleGeometry(0.15, 0.55, 3, 5), armor); armL.position.set(-0.5, 1.6, 0.55); armL.rotation.x = -1.2; armL.rotation.z = -0.5;
  // 加特林
  const gunPivot = new THREE.Group(); gunPivot.position.set(0.55, 1.45, 0.2);
  const gunBody = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 1.1, 8), dark); gunBody.rotation.x = Math.PI/2; gunBody.position.z = 0.3;
  const housing = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.45, 0.7), metal); housing.position.set(0, -0.05, 0.1);
  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.35, 0.12), dark); grip.position.set(0, -0.4, -0.1);
  const armR = new THREE.Mesh(new THREE.CapsuleGeometry(0.15, 0.4, 3, 5), armor); armR.position.set(0.05, -0.35, -0.3); armR.rotation.x = 0.9;
  const barrels = new THREE.Group(); barrels.position.z = 1.4;
  for(let i=0;i<6;i++){ const a = i/6*Math.PI*2; const b = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 1.7, 5), metal); b.rotation.x = Math.PI/2; b.position.set(Math.cos(a)*0.16, Math.sin(a)*0.16, 0); barrels.add(b); }
  const ring1 = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.1, 8), dark); ring1.rotation.x = Math.PI/2; ring1.position.z = 0.6; barrels.add(ring1);
  const ring2 = ring1.clone(); ring2.position.z = -0.4; barrels.add(ring2);
  const muzzle = new THREE.Object3D(); muzzle.position.z = 2.3;
  const beltAmmo = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.3, 0.9), M(0xc9a227, {metalness:.5})); beltAmmo.position.set(-0.3, 0.05, -0.35); beltAmmo.rotation.y = 0.4;
  gunPivot.add(gunBody, housing, grip, armR, barrels, muzzle, beltAmmo);
  root.add(legL, legR, torso, chest, belt, pack, packStripe, shL, shR, head, helmet, visor, armL, gunPivot);
  root.traverse(o=>{ if(o.isMesh) o.castShadow = true; });
  return { root, legL, legR, gunPivot, barrels, muzzle };
}
CH.sword = buildSwordsman(); CH.gun = buildGunner();
function useChar(cls){
  if(cur) bodyGroup.remove(cur.root);
  cur = CH[cls]; bodyGroup.add(cur.root); S.cls = cls;
  // 加特林初始速度更快
  const baseSpeed = cls==='gun' ? 13.5 : 12;
  if(S.running) S.speed = baseSpeed * (S.speed / 12);
  document.getElementById('heat').style.display = cls==='gun' ? 'block' : 'none';
  const ab = document.getElementById('atkBtn'); ab.classList.toggle('gun', cls==='gun'); ab.textContent = cls==='gun' ? '🔥' : '⚔️';
  document.getElementById('hint').innerHTML = cls==='sword'
    ? 'WASD 移动 · <b>J / 鼠标左键</b> 挥刀（三连斩） · <b>空格</b> 跳跃（空中攻击 = 坠地重斩） · <b>K / Shift</b> 冲刺'
    : 'WASD 移动 · <b>鼠标</b> 决定射击方向（自动开火） · <b>空格</b> 跳跃 · <b>K / Shift</b> 冲刺';
}

// ---------- 奶龙模型 ----------
const NL = {
  bodyMat: new THREE.MeshLambertMaterial({ color:0xffc21a, flatShading:true }),
  bellyMat: new THREE.MeshLambertMaterial({ color:0xfff1c2, flatShading:true }),
  eyeWhiteMat: new THREE.MeshLambertMaterial({ color:0xffffff, flatShading:true }),
  eyeMat: new THREE.MeshLambertMaterial({ color:0x1f9d55, emissive:0x0d4a28, emissiveIntensity:.8 }),
  pupilMat: new THREE.MeshBasicMaterial({ color:0x111111 }),
  mouthMat: new THREE.MeshBasicMaterial({ color:0x3a1010 }),
  hitMat: new THREE.MeshLambertMaterial({ color:0xffffff, emissive:0xffffff, emissiveIntensity:1 }),
  hitMat2: new THREE.MeshLambertMaterial({ color:0xff6a3a, emissive:0xff3a1a, emissiveIntensity:.9 }),
  smallBody: new THREE.SphereGeometry(0.55, 7, 6), smallHead: new THREE.SphereGeometry(0.5, 7, 6),
  belly: new THREE.SphereGeometry(0.4, 6, 5), eyeWhite: new THREE.SphereGeometry(0.13, 5, 4), eye: new THREE.SphereGeometry(0.09, 5, 4),
  pupil: new THREE.SphereGeometry(0.04, 4, 3), mouth: new THREE.BoxGeometry(0.34, 0.12, 0.1),
  arm: new THREE.CapsuleGeometry(0.11, 0.35, 2, 4), leg: new THREE.CylinderGeometry(0.16, 0.2, 0.4, 5), foot: new THREE.SphereGeometry(0.2, 5, 3), tail: new THREE.ConeGeometry(0.18, 0.9, 4),
  fatBody: new THREE.SphereGeometry(0.95, 8, 7), fatBelly: new THREE.SphereGeometry(0.72, 7, 6), fatHead: new THREE.SphereGeometry(0.42, 7, 6),
  fatLeg: new THREE.CylinderGeometry(0.26, 0.3, 0.55, 5), fatArm: new THREE.CapsuleGeometry(0.17, 0.5, 2, 4),
};
// ---------- 合批渲染（InstancedMesh）----------
// 每只奶龙 ~17 个部件，400 只 = 7000 次 draw call；合批后全场只有几十次
const BATCH_CAP = 1024;
const batches = new Map();   // key -> InstancedMesh
const batchList = [];
function getBatch(geo, mat, shadow){
  const key = geo.uuid + '|' + mat.uuid;
  let b = batches.get(key);
  if(!b){
    b = new THREE.InstancedMesh(geo, mat, BATCH_CAP); b.count = 0; b.frustumCulled = false;
    b.castShadow = !!shadow; b.receiveShadow = false;
    b.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    batches.set(key, b); batchList.push(b); scene.add(b);
  }
  return b;
}
function registerParts(g, flashList){
  const flashSet = new Set(flashList);
  const meshes = [];
  g.traverse(o=>{ if(o.isMesh){
    const shadow = (o.geometry===NL.smallBody||o.geometry===NL.fatBody||o.geometry===NL.smallHead||o.geometry===NL.fatHead);
    o.userData.b0 = getBatch(o.geometry, o.material, shadow);
    o.userData.b1 = flashSet.has(o) ? getBatch(o.geometry, NL.hitMat, shadow) : o.userData.b0;
    o.userData.b2 = flashSet.has(o) ? getBatch(o.geometry, NL.hitMat2, shadow) : o.userData.b0;
    meshes.push(o);
  }});
  g.userData.meshes = meshes;
  g.userData.flashMeshes = flashList;
}
const titleDecor = [];
function pushGroup(g, mode){
  g.updateMatrixWorld(true);
  const ms = g.userData.meshes;
  for(let k=0;k<ms.length;k++){ const o = ms[k]; const b = mode===1?o.userData.b1:mode===2?o.userData.b2:o.userData.b0; if(b.count<BATCH_CAP) b.setMatrixAt(b.count++, o.matrixWorld); }
}
let cullR2 = 60*60;
function syncBatches(){
  for(let i=0;i<batchList.length;i++) batchList[i].count = 0;
  const px = player.position.x, pz = player.position.z;
  for(let i=0;i<enemies.length;i++){
    const e = enemies[i], g = e.g;
    if(!e.boss){ const dx = g.position.x-px, dz = g.position.z-pz; if(dx*dx+dz*dz > cullR2) continue; }
    pushGroup(g, g.userData.hit|0);
  }
  for(let i=0;i<titleDecor.length;i++) pushGroup(titleDecor[i], 0);
  // 经验球
  gemBatch.count = 0;
  for(let i=0;i<gems.length;i++){ const o = gems[i].m; o.updateMatrix(); gemBatch.setMatrixAt(gemBatch.count++, o.matrix); }
  // 碎块
  for(const k in gibBatch) gibBatch[k].count = 0;
  for(let i=0;i<gibs.length;i++){ const gg = gibs[i]; if(gg.b.count<320){ gg.m.updateMatrix(); gg.b.setMatrixAt(gg.b.count++, gg.m.matrix); } }
  for(const k in gibBatch) gibBatch[k].instanceMatrix.needsUpdate = true;
  // 粒子
  for(const k in partBatch) partBatch[k].count = 0;
  for(let i=0;i<particles.length;i++){ const p = particles[i]; const b = partBatch[p.k]; if(b.count<BATCH_CAP){ p.m.updateMatrix(); b.setMatrixAt(b.count++, p.m.matrix); } }
  for(let i=0;i<batchList.length;i++){ const b = batchList[i]; if(b.count>0) b.instanceMatrix.needsUpdate = true; }
  gemBatch.instanceMatrix.needsUpdate = true;
  for(const k in partBatch) partBatch[k].instanceMatrix.needsUpdate = true;
}

