addEventListener('keydown', e=>{
  if(e.key==='Escape'){ e.preventDefault(); togglePause(); return; }
  if(!keys[e.code]){ if(e.code==='KeyJ') atkPressed = true; if(e.code==='Space') jumpPressed = true; if(e.code==='KeyK'||e.code==='ShiftLeft'||e.code==='ShiftRight') dashPressed = true; }
  keys[e.code]=true; if(e.code==='Space'||e.code.startsWith('Arrow')) e.preventDefault();
  if(e.code==='KeyJ') atkHeld = true;
});
