const joy = { active:false, dx:0, dz:0 };
{
  const el = document.getElementById('joy'), knob = document.getElementById('joyk');
  const upd = (t)=>{ const r = el.getBoundingClientRect(); let dx = t.clientX-(r.left+65), dy = t.clientY-(r.top+65); const l = Math.hypot(dx,dy); if(l>50){dx=dx/l*50;dy=dy/l*50;} knob.style.left=(40+dx)+'px'; knob.style.top=(40+dy)+'px'; joy.dx=dx/50; joy.dz=dy/50; };
  el.addEventListener('touchstart', e=>{joy.active=true; upd(e.touches[0]); e.preventDefault();},{passive:false});
  el.addEventListener('touchmove', e=>{upd(e.touches[0]); e.preventDefault();},{passive:false});
  el.addEventListener('touchend', ()=>{joy.active=false; joy.dx=joy.dz=0; knob.style.left='40px'; knob.style.top='40px';});
  const bind = (id, down, up) => { const b = document.getElementById(id); b.addEventListener('touchstart', e=>{ down(); e.preventDefault(); },{passive:false}); b.addEventListener('touchend', e=>{ up&&up(); e.preventDefault(); },{passive:false}); };
  bind('atkBtn', ()=>{ audio(); atkPressed=true; atkHeld=true; }, ()=>{ atkHeld=false; });
  bind('dashBtn', ()=>{ audio(); dashPressed=true; });
  bind('jumpBtn', ()=>{ audio(); jumpPressed=true; });
  // 摇杆触摸也解锁音频
  { const _o = el.ontouchstart; el.addEventListener('touchstart', ()=>audio(), {passive:true}); }
}
