  if(texts.length>Q.textMax) return;
  const key = n+color; let tex = textCache[key];
  if(!tex){ const c = document.createElement('canvas'); c.width=128; c.height=64; const x = c.getContext('2d'); x.font='bold 44px sans-serif'; x.textAlign='center'; x.lineWidth=6; x.strokeStyle='#000'; x.strokeText(String(n),64,46); x.fillStyle=color; x.fillText(String(n),64,46); tex = new THREE.CanvasTexture(c); textCache[key]=tex; }
  let mat = textMatCache[key]; if(!mat){ mat = new THREE.SpriteMaterial({ map:tex, transparent:true, depthTest:false }); textMatCache[key] = mat; }
  const sp = textPool.pop() || new THREE.Sprite(); sp.material = mat.clone(); sp.scale.set(2*sc,1*sc,1); sp.position.copy(p); sp.position.y += 2.4 + Math.random()*0.5; sp.position.x += (Math.random()-0.5);
