const SLAM = { arc:Math.PI, range:5.5, dmg:2.2, knock:22, launch:13 };
const slashGeoCache = {};
// 新月形斩痕：内窄外宽，带渐变透明的顶点色
function slashGeo(arc, inner=0.45){
  const k = arc.toFixed(2)+'|'+inner; if(slashGeoCache[k]) return slashGeoCache[k];
  const seg = Q.fx<0.5 ? 16 : 28, pos=[], col=[], idx=[];
  for(let i=0;i<=seg;i++){
    const t = i/seg, a = -arc + arc*2*t;
    // 新月：中间最宽，两端收尖
    const w = Math.sin(t*Math.PI); const rIn = 1 - (1-inner)*w; const rOut = 1 + 0.08*w;
    pos.push(Math.cos(a)*rIn, 0, Math.sin(a)*rIn, Math.cos(a)*rOut, 0, Math.sin(a)*rOut);
    const al = Math.pow(w, 0.6);
    col.push(1,1,1,al*0.35, 1,1,1,al);
  }
  for(let i=0;i<seg;i++){ const b=i*2; idx.push(b,b+1,b+2, b+1,b+3,b+2); }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos,3)); g.setAttribute('color', new THREE.Float32BufferAttribute(col,4)); g.setIndex(idx);
  slashGeoCache[k] = g; return g;
}
const slashPool = [];
function mkSlash(geo, mat){ let m = slashPool.pop(); if(!m){ m = new THREE.Mesh(geo, mat.clone()); return m; } m.geometry = geo; if(m.material.userData.src!==mat){ m.material.dispose(); m.material = mat.clone(); } m.material.opacity = mat.opacity; m.rotation.set(0,0,0); return m; }
