const slashMatGlow = new THREE.MeshBasicMaterial({ color:0x4fc3ff, vertexColors:true, transparent:true, opacity:0.9, side:THREE.DoubleSide, depthWrite:false, blending:THREE.AdditiveBlending });
const slashMatGlowBig = new THREE.MeshBasicMaterial({ color:0xffb040, vertexColors:true, transparent:true, opacity:0.95, side:THREE.DoubleSide, depthWrite:false, blending:THREE.AdditiveBlending });
[slashMatCore, slashMatGlow, slashMatGlowBig].forEach(m=>{ const oc = m.clone.bind(m); m.clone = ()=>{ const c = oc(); c.userData.src = m; return c; }; });
