const trailPts = []; // {tip:Vector3, base:Vector3, t}
const _tipW = new THREE.Vector3(), _baseW = new THREE.Vector3();
function updateTrail(dt, active){
  if(active && cur.bladeTip){
    cur.bladeTip.getWorldPosition(_tipW); cur.bladeBase.getWorldPosition(_baseW);
    trailPts.push({ tip:_tipW.clone(), base:_baseW.clone(), life:0.16 });
    if(trailPts.length>TRAIL_N) trailPts.shift();
  }
  for(let i=trailPts.length-1;i>=0;i--){ trailPts[i].life -= dt; if(trailPts[i].life<=0) trailPts.splice(i,1); }
  if(!Q.trail || trailPts.length<2){ trailMesh.visible=false; return; }
  trailMesh.visible = true;
  const pa = trailGeo.attributes.position.array, ca = trailGeo.attributes.color.array;
  const n = trailPts.length;
  for(let i=0;i<TRAIL_N;i++){
    const q = trailPts[Math.min(i, n-1)]; const k = Math.min(i,n-1)/(n-1); const al = Math.pow(k,1.5)*Math.min(1, q.life/0.16);
    pa[i*6]=q.base.x; pa[i*6+1]=q.base.y; pa[i*6+2]=q.base.z; pa[i*6+3]=q.tip.x; pa[i*6+4]=q.tip.y; pa[i*6+5]=q.tip.z;
    ca[i*8]=1;ca[i*8+1]=1;ca[i*8+2]=1;ca[i*8+3]=al*0.15; ca[i*8+4]=1;ca[i*8+5]=1;ca[i*8+6]=1;ca[i*8+7]=al;
  }
  trailGeo.attributes.position.needsUpdate = true; trailGeo.attributes.color.needsUpdate = true;
}
