  // ----- 生成 -----
  const minute = S.time/60;
  const rate = Math.min(3.5 + minute*3.0, Q.fx<0.3?12:IS_MOBILE?16:22);
  spawnTimer += dt*rate;
  while(spawnTimer>=1 && enemies.length<MAX_ENEMIES){ spawnTimer -= 1; const fatChance = Math.min(0.08 + minute*0.06, 0.45); const tiered = Math.random() < Math.min(minute*0.035, 0.3); spawnEnemy(Math.random()<fatChance?'fat':'small', tiered); }
  if(Math.floor(S.time)%45===0 && S.time%1<dt && S.time>5){ const wn = Math.min(40 + Math.floor(minute*8), 90); for(let i=0;i<wn && enemies.length<MAX_ENEMIES;i++){ const t = i%10===9 && minute>1 ? 'tank' : i%6===5 ? 'fat' : 'small'; spawnEnemy(t, minute>3 && i%4===0); } }
  // 巨型奶龙：开局 60s 第一只，之后按分钟数决定同时在场数量（最多 4），时间到就来新的
