  for(let i=rings.length-1;i>=0;i--){ const r = rings[i]; r.life -= dt; const k = 1 - r.life/r.max; r.m.scale.setScalar(0.5 + r.R*Math.sqrt(k)); r.m.material.opacity = (1-k)*0.9; if(r.life<=0){ scene.remove(r.m); ringPool.push(r.m); rings.splice(i,1);} }
